import unittest
import array_pointer as app

class Behavior(unittest.TestCase):
    def test_resolve(self):
        d={'bins':['north',{'label':'south'}], '01':'literal', '':17, 'a/b':{'~key':8},'é':'accent'}
        self.assertIs(app.resolve(d,''),d)
        for p,w in [('/bins/0','north'),('/bins/1/label','south'),('/01','literal'),('/',17),('/a~1b/~0key',8),('/é','accent')]:
            self.assertEqual(app.resolve(d,p),w)
        for p in ['/bins/01','/bins/-','/bins/-1','/bins/+1','/bins/2','/bins/','/bins/１','bins/0','/missing','/bins/0/x','/a~2b','/a~']:
            with self.subTest(pointer=p),self.assertRaises(ValueError):
                app.resolve(d,p)
        with self.assertRaises(ValueError):app.resolve(d,'/e\u0301')


