class PointerEdges(unittest.TestCase):
    def test_roots_and_decoding(self):
        import copy
        d = {'~1': {'~01': [None, False, 0]}, 'items': [1, 2]}
        before = copy.deepcopy(d)
        self.assertIs(app.resolve(d, '/~01/~001/0'), None)
        self.assertIs(app.resolve(d, '/~01/~001/1'), False)
        self.assertEqual(app.resolve([{'x': 9}], '/0/x'), 9)
        self.assertEqual(app.resolve(42, ''), 42)
        self.assertEqual(app.resolve(d, '/~01/~001/2'), 0)
        with self.assertRaises(ValueError): app.resolve(d, '/items/2')
        self.assertEqual(d, before)

